using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
using static HakutaiKagami.Tests.CareerMilitaryTests;
namespace HakutaiKagami.Tests;
public sealed class MilitaryInquiryTests
{
    static string Query(WorldSession s,string label="first"){
        var career=s.DiagnosticSnapshot().Career!.Requests.First(q=>q.Input.Action==CareerAction.Apply).Case;
        Assert.Equal(ResultCode.Accepted,s.DecideCareer(new(new("request:military-query/"+label),CareerAction.Inquire,career),s.PlayerControl,s.Revision).Code);At(s,s.Seconds+1);return s.DiagnosticSnapshot().Military!.Events.Last(e=>e.Effect==MilitaryEffect.StatusSent).Message;
    }
    static void Recover(WorldSession s,string label="first"){var id=Query(s,label);At(s,Due(s,id));Open(s,id);}
    static string LosePermission(WorldSession s){Join(s);Decide(s,MilitaryAction.Request);At(s,s.Seconds+2);Open(s,Notice(s,MilitaryEffect.Offered));Decide(s,MilitaryAction.Accept);At(s,s.Seconds+1);string id=Notice(s,MilitaryEffect.Permission);s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,id));At(s,s.Seconds+2);return id;}
    static void OriginalUnknown(WorldSession s,string id){Assert.False(MessageFlow.Knows(s.DiagnosticSnapshot().Messaging,id,s.PlayerControl.Value));Assert.DoesNotContain(s.DiagnosticSnapshot().Messaging.Receipts,r=>r.MessageId==id);}
    [Fact]public void LostPermissionIsQuotedWithoutForgingOriginalReceipt(){var s=New();string original=LosePermission(s);Assert.False(CareerMilitary.View(s,s.PlayerControl).CanPickup);Recover(s);Assert.True(CareerMilitary.View(s,s.PlayerControl).CanPickup);OriginalUnknown(s,original);Assert.Empty(s.DiagnosticSnapshot().CommandMandates!);Decide(s,MilitaryAction.Pickup);Assert.True(CareerMilitary.Custody(s.DiagnosticSnapshot()));Assert.Single(s.DiagnosticSnapshot().CommandMandates!);}
    [Fact]public void LostOfferCanBeKnownFromPhysicalQuoteWithinOriginalDeadline(){var s=New();Join(s);Decide(s,MilitaryAction.Request);At(s,s.Seconds+1);string original=Notice(s,MilitaryEffect.Offered);s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,original));At(s,s.Seconds+2);Recover(s);OriginalUnknown(s,original);Assert.True(CareerMilitary.View(s,s.PlayerControl).CanAccept);Decide(s,MilitaryAction.Accept);At(s,s.Seconds+2);Open(s,Notice(s,MilitaryEffect.Permission));Decide(s,MilitaryAction.Pickup);Assert.Single(s.DiagnosticSnapshot().Military!.Events,e=>e.Effect==MilitaryEffect.Offered);}
    [Fact]public void DeliveredButUnopenedStatusDoesNotRevealPermission(){var s=New();LosePermission(s);string id=Query(s);var actor=s.GetActorView(s.PlayerControl);Assert.DoesNotContain(actor.Messages,m=>m.Id.Value==id);At(s,Due(s,id));Assert.Null(s.GetActorView(s.PlayerControl).Messages.Single(m=>m.Id.Value==id).KnownBody);Assert.False(CareerMilitary.View(s,s.PlayerControl).CanPickup);Open(s,id);Assert.True(CareerMilitary.View(s,s.PlayerControl).CanPickup);}
    [Fact]public void QuoteDoesNotExtendTheOriginalOfferDeadline(){var s=New();Join(s);Decide(s,MilitaryAction.Request);At(s,s.Seconds+1);string original=Notice(s,MilitaryEffect.Offered);s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,original));At(s,s.Seconds+125);Recover(s);Assert.False(CareerMilitary.View(s,s.PlayerControl).CanAccept);Assert.Empty(s.DiagnosticSnapshot().CommandMandates!);}
    [Fact]public void PrincipalWithoutReceivedApplicationReportsNoRecordOnly(){var s=New();Join(s);Decide(s,MilitaryAction.Request);string original=s.DiagnosticSnapshot().Military!.Requests.Last().Message!;s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,original));At(s,s.Seconds+2);Recover(s);Assert.Contains("記録なし",CareerMilitary.View(s,s.PlayerControl).Status);Assert.False(CareerMilitary.View(s,s.PlayerControl).CanAccept);Assert.False(CareerMilitary.View(s,s.PlayerControl).CanPickup);}
    [Fact]public void LostHandbackNoticeIsRecoveredWithoutChangingCommandAgain(){var s=New();Pickup(s);Assert.Equal(ResultCode.Accepted,s.ReportEngagement(new("request:reported-return"),s.PlayerControl,s.Revision).Code);Decide(s,MilitaryAction.Return);At(s,s.Seconds+1);string original=Notice(s,MilitaryEffect.Returned);s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,original));At(s,s.Seconds+2);Assert.True(CareerMilitary.View(s,s.PlayerControl).Custody);var mandate=ContractJson.Write(s.DiagnosticSnapshot().CommandMandates);Recover(s);Assert.False(CareerMilitary.View(s,s.PlayerControl).Custody);OriginalUnknown(s,original);Assert.Equal(mandate,ContractJson.Write(s.DiagnosticSnapshot().CommandMandates));}
    [Fact]public void LateOldStatusCannotUndoKnownHandback(){var s=New();Pickup(s);string old=Query(s,"old-custody");s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,old));At(s,s.Seconds+2);Assert.Equal(ResultCode.Accepted,s.ReportEngagement(new("request:return-report"),s.PlayerControl,s.Revision).Code);Decide(s,MilitaryAction.Return);At(s,s.Seconds+2);Open(s,Notice(s,MilitaryEffect.Returned));var mandate=ContractJson.Write(s.DiagnosticSnapshot().CommandMandates);s.DiagnosticRecoverLocalCourier(old,1);At(s,s.Seconds+2);Open(s,old);Assert.False(CareerMilitary.View(s,s.PlayerControl).Custody);Assert.False(CareerMilitary.View(s,s.PlayerControl).CanPickup);Assert.Equal(mandate,ContractJson.Write(s.DiagnosticSnapshot().CommandMandates));Assert.Single(s.DiagnosticSnapshot().Military!.Events,e=>e.Effect==MilitaryEffect.Returned);}
    [Fact]public void QueryDoesNotGrantCommandOrMakeOriginalKnown(){var s=New();Permission(s);var units=s.DiagnosticSnapshot().Units.Select(u=>(u.Id,u.Army,u.Commander,u.Organization,u.Soldiers)).ToArray();Recover(s);Assert.Equal(units,s.DiagnosticSnapshot().Units.Select(u=>(u.Id,u.Army,u.Commander,u.Organization,u.Soldiers)).ToArray());Assert.Empty(s.DiagnosticSnapshot().CommandMandates!);}
    [Fact]public void RetryRequiresPersonallyReceivedFailureReport(){var s=New();Join(s);Decide(s,MilitaryAction.Request);string original=s.DiagnosticSnapshot().Military!.Requests.Last().Message!;string failed=MessageFlow.Latest(s.DiagnosticSnapshot().Messaging,original).Id;s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,original));At(s,Due(s,original));Assert.Null(CareerMilitary.Retryable(s,s.PlayerControl));Assert.Equal(ResultCode.NotAvailable,s.RetryMilitaryRequest(original,failed,s.PlayerControl,s.Revision).Code);At(s,s.Seconds+1);Assert.NotNull(CareerMilitary.Retryable(s,s.PlayerControl));Assert.Equal(ResultCode.Accepted,s.RetryMilitaryRequest(original,failed,s.PlayerControl,s.Revision).Code);}
    [Fact]public void RetryKeepsLogicalIdBodyAndIsIdempotentPerFailedAttempt(){var s=New();Join(s);Decide(s,MilitaryAction.Request);string original=s.DiagnosticSnapshot().Military!.Requests.Last().Message!;var envelope=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Id==original);s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,original));At(s,s.Seconds+2);string failed=MessageFlow.Latest(s.DiagnosticSnapshot().Messaging,original).Id;Assert.Equal(ResultCode.Accepted,s.RetryMilitaryRequest(original,failed,s.PlayerControl,s.Revision).Code);var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.AlreadyAccepted,s.RetryMilitaryRequest(original,failed,s.PlayerControl,0).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));Assert.Equal(envelope,s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Id==original));Assert.Equal(2,s.DiagnosticSnapshot().Messaging.Attempts.Count(a=>a.MessageId==original));}
    [Fact]public void LateOriginalAndRetriedApplicationCreateOnlyOneOffer(){var s=New();Join(s);Decide(s,MilitaryAction.Request);string original=s.DiagnosticSnapshot().Military!.Requests.Last().Message!;s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,original));At(s,s.Seconds+2);string failed=MessageFlow.Latest(s.DiagnosticSnapshot().Messaging,original).Id;Assert.Equal(ResultCode.Accepted,s.RetryMilitaryRequest(original,failed,s.PlayerControl,s.Revision).Code);At(s,s.Seconds+2);s.DiagnosticRecoverLocalCourier(original,1);At(s,s.Seconds+2);Assert.Single(s.DiagnosticSnapshot().Military!.Events,e=>e.Effect==MilitaryEffect.Offered);Assert.Single(s.DiagnosticSnapshot().Messaging.Receipts,r=>r.MessageId==original);Assert.True(s.DiagnosticSnapshot().Messaging.Attempts.Single(a=>a.Id==failed).ArrivedLate);}
    [Fact]public void ThreeFailedAttemptsCannotSilentlyCreateFourth(){var s=New();Join(s);Decide(s,MilitaryAction.Request);string original=s.DiagnosticSnapshot().Military!.Requests.Last().Message!;for(int i=0;i<3;i++){s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,original));At(s,s.Seconds+2);string failed=MessageFlow.Latest(s.DiagnosticSnapshot().Messaging,original).Id;Assert.Equal(i<2?ResultCode.Accepted:ResultCode.NotAvailable,s.RetryMilitaryRequest(original,failed,s.PlayerControl,s.Revision).Code);}Assert.Null(CareerMilitary.Retryable(s,s.PlayerControl));Assert.Equal(3,s.DiagnosticSnapshot().Messaging.Attempts.Count(a=>a.MessageId==original));}
    [Fact]public void OtherActorAndForeignMessageCannotUseMilitaryRetry(){var s=New();Join(s);Decide(s,MilitaryAction.Request);string id=s.DiagnosticSnapshot().Military!.Requests.Last().Message!;Assert.Equal(ResultCode.NotAvailable,s.RetryMilitaryRequest(id,MessageFlow.Latest(s.DiagnosticSnapshot().Messaging,id).Id,RetainerStart.Lord,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.RetryMilitaryRequest(s.DiagnosticSnapshot().Career!.Requests.First().Message,"missing",s.PlayerControl,s.Revision).Code);}
    [Theory][InlineData(false)][InlineData(true)]public void RestoreBeforeOrAfterQuotePreservesFullWorld(bool opened){var s=New();LosePermission(s);string id=Query(s);At(s,Due(s,id));if(opened)Open(s,id);s.SetPaused(true);var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"military-query-"+Guid.NewGuid().ToString("N")),s.DiagnosticSnapshot().Definitions);store.Save(s,"state",s.DiagnosticSnapshot().WorldId,new(0,1));var host=new WorldSessionHost(New());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("state"),host.Current,host.Current.Revision));if(!opened){Open(s,id);Open(host.Current,id);}Decide(s,MilitaryAction.Pickup);Decide(host.Current,MilitaryAction.Pickup);At(s,s.Seconds+3);At(host.Current,s.Seconds);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));}
    [Fact]public void LiteralMilitaryBeforeInquiryStillLoadsAndStartsIdentically(){foreach(var n in new[]{"initial","active"}){var bytes=File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory,"Fixtures","military-bd631ba-"+n+".json"));var w=ContractJson.Read<ContractWorld>(bytes);ContractValidation.Validate(w);Assert.Equal(bytes,ContractJson.Write(w));if(n=="initial")Assert.Equal(ContractJson.CanonicalHash(w),ContractJson.CanonicalHash(CareerMilitary.Create("検証軍務照会前")));}}
    [Theory][InlineData("body")][InlineData("source")][InlineData("opening")]
    public void ForgedStatusCannotLoad(string kind){var s=New();LosePermission(s);Recover(s);var w=s.DiagnosticSnapshot();var e=w.Military!.Events.Last(x=>x.Effect==MilitaryEffect.StatusSent);if(kind=="body")w.Messaging.Messages=w.Messaging.Messages.Select(m=>m.Id==e.Message?m with{Body="{}"}:m).ToArray();if(kind=="source")w.Military=w.Military with{Events=w.Military.Events.Select(x=>x==e?x with{Source=w.Career!.Requests.First().Message}:x).ToArray()};if(kind=="opening")w.Military=w.Military with{Openings=w.Military.Openings.Select(o=>o.Message==e.Message?o with{Revision=w.CommitSequence+1}:o).ToArray()};Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}

    [Fact]public void TimerOnlyRoadRecoveryRemainsRejected(){var s=New();Join(s);Decide(s,MilitaryAction.Request);string original=s.DiagnosticSnapshot().Military!.Requests.Last().Message!;s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,original));At(s,s.Seconds+2);Assert.Throws<InvalidDataException>(()=>s.DiagnosticTransport((m,t)=>MessageFlow.ScheduleLate(m,original,1,t,30)));}
    [Fact]public void RecoveredOriginalDoesNotHomeToAMovingRecipient(){var s=New();string original=LosePermission(s);Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:away-from-recovered-letter","kofu"),s.Revision).Code);At(s,s.Seconds+5);s.DiagnosticRecoverLocalCourier(original,1);At(s,s.Seconds+2);var w=s.DiagnosticSnapshot();Assert.Equal(AttemptStatus.Rejected,MessageFlow.Latest(w.Messaging,original).Status);Assert.DoesNotContain(w.Messaging.Receipts,r=>r.MessageId==original);Assert.False(MessageFlow.Knows(w.Messaging,original,s.PlayerControl.Value));}
    [Fact]public void PendingPhysicalRecoveryRestoresAndContinuesIdentically(){var s=New();string original=LosePermission(s);s.DiagnosticRecoverLocalCourier(original,1);s.SetPaused(true);var w=s.DiagnosticSnapshot();Assert.NotNull(w.CourierRecoveries);Assert.Equal(1,w.CourierRecoveries!.Single().DueAt-w.ElapsedSeconds);var copy=new WorldSession(ContractJson.Read<ContractWorld>(ContractJson.Write(w)));At(s,s.Seconds+2);At(copy,s.Seconds);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(copy.DiagnosticSnapshot()));Open(s,original);Assert.True(CareerMilitary.View(s,s.PlayerControl).CanPickup);}
    [Theory][InlineData("path")][InlineData("address")][InlineData("due")]
    public void ForgedRecoveryCannotLoad(string kind){var s=New();string original=LosePermission(s);s.DiagnosticRecoverLocalCourier(original,1);var w=s.DiagnosticSnapshot();var entry=w.CourierRecoveries!.Single();if(kind=="path")w.CourierRecoveries=[entry with{Origin=new(entry.Origin.X+1000,entry.Origin.Y)}];if(kind=="address")w.CourierRecoveries=[entry with{Address=new(entry.Address.X+1000,entry.Address.Y)}];if(kind=="due")w.CourierRecoveries=[entry with{DueAt=entry.DueAt+10}];Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
}
